import {
  ApiPlaygroundBlock,
  type ApiMockHandler,
} from "@/components/custom/blocks/ApiPlaygroundBlock";

export default function UsersEndpointDocs() {
  // Decide how the playground responds to whatever the reader types.
  // This handler receives method, url, headers, params and body.
  const handleApiMock: ApiMockHandler = async (req) => {
    await new Promise((resolve) => setTimeout(resolve, 500)); // Latency

    let parsedBody = null;
    if (req.method !== "GET" && req.body) {
      try {
        parsedBody = JSON.parse(req.body);
      } catch {
        return {
          status: 400,
          timeMs: 15,
          data: { error: "bad_request", message: "Invalid JSON in request body." },
        };
      }
    }

    return {
      status: req.method === "POST" ? 201 : 200,
      timeMs: 120,
      data: {
        success: true,
        resource: req.url.split("/").pop() || "unknown",
        received_headers: req.headers.filter((h) => h.enabled).length,
        payload: parsedBody || "No body provided",
      },
    };
  };

  return (
    <ApiPlaygroundBlock
      defaultUrl="https://api.acme.com/v1/customers"
      defaultMethod="POST"
      mockHandler={handleApiMock}
    />
  );
}

"use client";

import { cn } from "@/lib/utils";
import { SelectBlock } from "./SelectBlock";
import {
  Activity,
  Check,
  CheckCircle2,
  Clock,
  Play,
  Plus,
  TerminalSquare,
  Trash2,
  XCircle,
} from "lucide-react";
import React, { forwardRef, useState } from "react";
import { getThemeStyles } from "./api-playground-theme";

// ==========================================
// THEME & CONFIGURATION
// ==========================================
export type ApiColor =
  | "primary"
  | "default"
  | "lavender"
  | "indigo"
  | "rose"
  | "emerald"
  | "zinc"
  | (string & {});
export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

// Theme colour fed to SelectBlock so the dropdown highlight, ring and chevron
// keep the per-method colour coding of the old native <select>.
const methodThemeColors: Record<HttpMethod, string> = {
  GET: "#3b82f6",
  POST: "#22c55e",
  PUT: "#f97316",
  PATCH: "#eab308",
  DELETE: "#ef4444",
};

const METHOD_OPTIONS = (
  ["GET", "POST", "PUT", "PATCH", "DELETE"] as HttpMethod[]
).map((m) => ({ label: m, value: m }));

// ==========================================
// INTERFACES
// ==========================================
export interface KeyValuePair {
  id: string;
  key: string;
  value: string;
  enabled: boolean;
}

export interface ApiResponse {
  status: number;
  timeMs: number;
  data: unknown;
}

/** The request snapshot handed to `mockHandler` when the reader hits Send. */
export interface ApiPlaygroundRequest {
  method: HttpMethod;
  url: string;
  headers: KeyValuePair[];
  params: KeyValuePair[];
  body: string;
}

/**
 * Decides how the playground answers a request. Annotate the whole handler with
 * this type rather than the `req` parameter alone — that way the returned
 * response shape is checked too:
 *
 *   const handleApiMock: ApiMockHandler = async (req) => { ... };
 */
export type ApiMockHandler = (
  req: ApiPlaygroundRequest,
) => Promise<ApiResponse>;

export interface ApiPlaygroundProps
  extends React.HTMLAttributes<HTMLDivElement> {
  defaultUrl?: string;
  defaultMethod?: HttpMethod;
  color?: ApiColor;
  mockHandler?: ApiMockHandler;
}

// Helper to rebuild URL with query params
const buildFullUrl = (currentUrl: string, paramsList: KeyValuePair[]) => {
  const basePath = currentUrl.split("?")[0];
  const activeParams = paramsList.filter(
    (p) => p.enabled && p.key.trim() !== "",
  );

  if (activeParams.length === 0) {
    return basePath;
  }

  const queryParts = activeParams.map((p) => {
    const k = encodeURIComponent(p.key.trim());
    const v = encodeURIComponent(p.value);
    return `${k}=${v}`;
  });

  return `${basePath}?${queryParts.join("&")}`;
};

// Helper to parse query parameters from URL string
const parseParamsFromUrl = (fullUrl: string): KeyValuePair[] => {
  const queryIndex = fullUrl.indexOf("?");
  if (queryIndex === -1) return [];

  const queryString = fullUrl.slice(queryIndex + 1);
  if (!queryString) return [];

  const searchParams = new URLSearchParams(queryString);
  const parsed: KeyValuePair[] = [];

  searchParams.forEach((value, key) => {
    parsed.push({
      id: Math.random().toString(36).substring(7),
      key,
      value,
      enabled: true,
    });
  });

  return parsed;
};

// ==========================================
// COMPONENT
// ==========================================
export const ApiPlaygroundBlock = forwardRef<
  HTMLDivElement,
  ApiPlaygroundProps
>(
  (
    {
      defaultUrl = "https://api.example.com/v1/users",
      defaultMethod = "GET",
      color = "primary",
      mockHandler,
      className,
      ...props
    },
    ref,
  ) => {
    const { theme, style } = getThemeStyles(color as string);

    // State
    const [method, setMethod] = useState<HttpMethod>(defaultMethod);
    const [url, setUrl] = useState(() => defaultUrl);
    const [activeTab, setActiveTab] = useState<"params" | "headers" | "body">(
      "params",
    );

    const [params, setParams] = useState<KeyValuePair[]>(() => {
      const initialParsed = parseParamsFromUrl(defaultUrl);
      return initialParsed.length > 0
        ? initialParsed
        : [{ id: "1", key: "", value: "", enabled: true }];
    });
    const [headers, setHeaders] = useState<KeyValuePair[]>([
      {
        id: "h1",
        key: "Authorization",
        value: "Bearer sk_test_...",
        enabled: true,
      },
      {
        id: "h2",
        key: "Content-Type",
        value: "application/json",
        enabled: true,
      },
    ]);
    const [body, setBody] = useState("{\n  \n}");

    const [isLoading, setIsLoading] = useState(false);
    const [response, setResponse] = useState<ApiResponse | null>(null);

    // Dynamic 2-Way Binding Sync Handlers
    const syncParamsToUrl = (newParams: KeyValuePair[]) => {
      setParams(newParams);
      setUrl((prevUrl) => buildFullUrl(prevUrl, newParams));
    };

    const handleAddPair = (
      setter: React.Dispatch<React.SetStateAction<KeyValuePair[]>>,
    ) => {
      if (setter === setParams) {
        const next = [
          ...params,
          {
            id: Math.random().toString(36).substring(7),
            key: "",
            value: "",
            enabled: true,
          },
        ];
        syncParamsToUrl(next);
      } else {
        setter((prev) => [
          ...prev,
          {
            id: Math.random().toString(36).substring(7),
            key: "",
            value: "",
            enabled: true,
          },
        ]);
      }
    };

    const handleUpdatePair = (
      setter: React.Dispatch<React.SetStateAction<KeyValuePair[]>>,
      id: string,
      field: keyof KeyValuePair,
      value: string | boolean,
    ) => {
      if (setter === setParams) {
        const next = params.map((p) =>
          p.id === id ? { ...p, [field]: value } : p,
        );
        syncParamsToUrl(next);
      } else {
        setter((prev) =>
          prev.map((p) => (p.id === id ? { ...p, [field]: value } : p)),
        );
      }
    };

    const handleRemovePair = (
      setter: React.Dispatch<React.SetStateAction<KeyValuePair[]>>,
      id: string,
    ) => {
      if (setter === setParams) {
        const next = params.filter((p) => p.id !== id);
        syncParamsToUrl(next);
      } else {
        setter((prev) => prev.filter((p) => p.id !== id));
      }
    };

    const handleUrlChange = (newUrl: string) => {
      setUrl(newUrl);
      const parsed = parseParamsFromUrl(newUrl);
      if (parsed.length > 0) {
        setParams(parsed);
      }
    };

    const handleSend = async () => {
      setIsLoading(true);
      setResponse(null);

      const executeRequest =
        mockHandler ||
        (async (req) => {
          await new Promise((resolve) => setTimeout(resolve, 600));

          let parsedBody: unknown = null;
          if (req.method !== "GET" && req.body) {
            try {
              parsedBody = JSON.parse(req.body);
            } catch {
              parsedBody = req.body;
            }
          }

          const activeHeaders = req.headers
            .filter((h) => h.enabled && h.key)
            .reduce<Record<string, string>>((acc, h) => {
              acc[h.key] = h.value;
              return acc;
            }, {});

          const activeParams = req.params
            .filter((p) => p.enabled && p.key)
            .reduce<Record<string, string>>((acc, p) => {
              acc[p.key] = p.value;
              return acc;
            }, {});

          return {
            status: req.method === "POST" ? 201 : 200,
            timeMs: Math.floor(Math.random() * 150) + 50,
            data: {
              message: "Success",
              echo: {
                method: req.method,
                url: req.url,
                params: Object.keys(activeParams).length > 0 ? activeParams : undefined,
                headers: Object.keys(activeHeaders).length > 0 ? activeHeaders : undefined,
                payload: req.method !== "GET" ? (parsedBody ?? "No body provided") : undefined,
              },
            },
          };
        });

      try {
        const res = await executeRequest({
          method,
          url,
          headers,
          params,
          body,
        });
        setResponse(res);
      } catch (error) {
        setResponse({
          status: 500,
          timeMs: 0,
          data: {
            error:
              error instanceof Error && error.message
                ? error.message
                : "Internal Server Error",
          },
        });
      } finally {
        setIsLoading(false);
      }
    };

    // Render Key-Value Editor (Mobile Optimized)
    const renderKvEditor = (
      items: KeyValuePair[],
      setter: React.Dispatch<React.SetStateAction<KeyValuePair[]>>,
    ) => (
      <div className="flex flex-col gap-2">
        {items.map((item) => (
          <div
            key={item.id}
            className="flex items-center gap-1.5 sm:gap-2 group"
          >
            <label className="relative flex items-center justify-center cursor-pointer shrink-0">
              <input
                type="checkbox"
                checked={item.enabled}
                onChange={(e) =>
                  handleUpdatePair(setter, item.id, "enabled", e.target.checked)
                }
                className="peer sr-only"
              />
              <div
                className={cn(
                  "w-4 h-4 rounded flex items-center justify-center border transition-all duration-150 peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-1",
                  item.enabled
                    ? cn(theme.bg, theme.checkboxBorder ?? theme.border)
                    : "border-input bg-background hover:border-foreground/40",
                )}
              >
                <Check
                  className={cn(
                    "w-3 h-3 stroke-[3] transition-transform duration-150",
                    item.enabled ? "scale-100 opacity-100" : "scale-0 opacity-0",
                  )}
                />
              </div>
            </label>
            <input
              type="text"
              placeholder="Key"
              value={item.key}
              onChange={(e) =>
                handleUpdatePair(setter, item.id, "key", e.target.value)
              }
              className="w-1/2 min-w-0 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-background border border-input rounded-md outline-none focus:border-ring font-mono transition-colors"
              disabled={!item.enabled}
            />
            <input
              type="text"
              placeholder="Value"
              value={item.value}
              onChange={(e) =>
                handleUpdatePair(setter, item.id, "value", e.target.value)
              }
              className="w-1/2 min-w-0 px-2 sm:px-3 py-1.5 text-xs sm:text-sm bg-background border border-input rounded-md outline-none focus:border-ring font-mono transition-colors"
              disabled={!item.enabled}
            />
            <button
              onClick={() => handleRemovePair(setter, item.id)}
              className="p-1.5 text-muted-foreground hover:text-red-500 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-all rounded-md hover:bg-red-50 dark:hover:bg-red-500/10 shrink-0 cursor-pointer"
              title="Remove pair"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ))}
        <button
          onClick={() => handleAddPair(setter)}
          className="flex items-center gap-1.5 text-xs font-semibold text-muted-foreground hover:text-foreground w-max mt-2 transition-colors cursor-pointer"
        >
          <Plus className="w-3.5 h-3.5" /> Add{" "}
          {activeTab === "params" ? "Parameter" : "Header"}
        </button>
      </div>
    );

    return (
      <div
        ref={ref}
        className={cn(
          "w-full grid grid-cols-1 lg:grid-cols-2 gap-4 rounded-2xl bg-transparent border-none shadow-none",
          className,
        )}
        style={style}
        {...props}
      >
        {/* LEFT PANE: REQUEST BUILDER */}
        <div className="flex flex-col gap-4 min-w-0">
          {/* ── RESPONSIVE URL BAR ─────────────────────────────────────── */}
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 p-1.5 sm:p-2 bg-card border border-border rounded-xl">
            <div className="flex items-center gap-2 flex-1 min-w-0">
              <SelectBlock
                options={METHOD_OPTIONS}
                value={method}
                onChange={(v) => setMethod(v as HttpMethod)}
                color={methodThemeColors[method]}
                variant="filled"
                inputSize="sm"
                className="w-[104px] shrink-0"
              />

              <input
                type="text"
                value={url}
                onChange={(e) => handleUrlChange(e.target.value)}
                className="w-full min-w-0 bg-transparent px-2 text-xs sm:text-sm font-mono text-foreground outline-none truncate"
                placeholder="https://api.example.com..."
              />
            </div>

            <button
              onClick={handleSend}
              disabled={isLoading}
              className={cn(
                "flex items-center justify-center gap-2 h-9 px-4 rounded-lg text-sm font-semibold transition-all disabled:opacity-50 shrink-0 w-full sm:w-auto cursor-pointer",
                theme.bg,
                !isLoading && theme.glow,
              )}
            >
              {isLoading ? (
                <Activity className="w-4 h-4 animate-pulse" />
              ) : (
                <>
                  <Play className="w-4 h-4 fill-current" />
                  Send
                </>
              )}
            </button>
          </div>

          {/* Config Tabs */}
          <div className="flex flex-col flex-1 bg-card border border-border rounded-xl overflow-hidden min-h-[250px] min-w-0">
            {/* ── SCROLLABLE TABS ───────────────────────────────────────── */}
            <div className="flex items-center border-b border-border bg-muted/50 px-2 pt-2 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
              {(["params", "headers", "body"] as const).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={cn(
                    "px-3 sm:px-4 py-2 text-xs font-semibold capitalize transition-all border-b-2 whitespace-nowrap shrink-0 cursor-pointer",
                    activeTab === tab
                      ? cn(theme.tabBorder ?? theme.border ?? "border-primary", theme.text)
                      : "border-transparent text-muted-foreground hover:text-foreground",
                  )}
                >
                  {tab}
                  {tab === "params" &&
                    params.filter((p) => p.key).length > 0 &&
                    ` (${params.filter((p) => p.key).length})`}
                  {tab === "headers" &&
                    headers.filter((p) => p.key).length > 0 &&
                    ` (${headers.filter((p) => p.key).length})`}
                  {tab === "body" &&
                    method !== "GET" &&
                    body.trim().length > 2 &&
                    " (Raw)"}
                </button>
              ))}
            </div>

            <div className="p-3 sm:p-4 flex-1 overflow-y-auto">
              {activeTab === "params" && renderKvEditor(params, setParams)}
              {activeTab === "headers" && renderKvEditor(headers, setHeaders)}
              {activeTab === "body" && (
                <div className="w-full h-full flex flex-col relative group">
                  {method === "GET" && (
                    <div className="absolute inset-0 bg-card/80 backdrop-blur-[1px] z-10 flex items-center justify-center rounded-lg p-4 text-center">
                      <p className="text-xs sm:text-sm font-medium text-muted-foreground">
                        GET requests typically do not have a body.
                      </p>
                    </div>
                  )}
                  <textarea
                    value={body}
                    onChange={(e) => setBody(e.target.value)}
                    className="w-full h-full min-h-[150px] p-3 text-xs sm:text-sm font-mono bg-muted border border-input rounded-lg outline-none focus:border-ring resize-none transition-colors"
                    spellCheck={false}
                  />
                </div>
              )}
            </div>
          </div>
        </div>

        {/* RIGHT PANE: RESPONSE VIEWER */}
        <div className="flex flex-col bg-card rounded-xl overflow-hidden border border-border min-h-[300px] min-w-0">
          {/* ── RESPONSIVE TERMINAL HEADER ──────────────────────────────── */}
          <div className="flex flex-wrap items-center justify-between gap-2 px-3 sm:px-4 py-2.5 bg-muted/80 border-b border-border">
            <div className="flex items-center gap-2">
              <TerminalSquare className="w-4 h-4 text-muted-foreground shrink-0" />
              <span className="text-xs font-semibold text-muted-foreground">
                Response
              </span>
            </div>

            {response && (
              <div className="flex items-center gap-3 sm:gap-4 text-[11px] font-mono">
                <div
                  className={cn(
                    "flex items-center gap-1 sm:gap-1.5 font-semibold",
                    response.status < 400
                      ? "text-emerald-600 dark:text-emerald-400"
                      : "text-red-600 dark:text-red-400",
                  )}
                >
                  {response.status < 400 ? (
                    <CheckCircle2 className="w-3 h-3 shrink-0" />
                  ) : (
                    <XCircle className="w-3 h-3 shrink-0" />
                  )}
                  Status: {response.status}
                </div>
                <div className="flex items-center gap-1 sm:gap-1.5 text-muted-foreground border-l border-border pl-3 sm:pl-4">
                  <Clock className="w-3 h-3 shrink-0" />
                  {response.timeMs}ms
                </div>
              </div>
            )}
          </div>

          {/* Terminal Body */}
          <div className="relative flex-1 p-3 sm:p-4 overflow-y-auto overflow-x-auto">
            {isLoading ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-card/80">
                <Activity className={cn("w-6 h-6 animate-pulse", theme.text)} />
                <span className="text-xs font-mono text-muted-foreground animate-pulse">
                  Awaiting response...
                </span>
              </div>
            ) : response ? (
              <pre className="text-xs sm:text-[13px] font-mono leading-relaxed text-foreground">
                <code>{JSON.stringify(response.data, null, 2)}</code>
              </pre>
            ) : (
              <div className="h-full flex flex-col items-center justify-center gap-2 opacity-50 dark:opacity-30 select-none text-center p-4">
                <TerminalSquare className="w-10 sm:w-12 h-10 sm:h-12 text-muted-foreground mb-2" />
                <p className="text-xs sm:text-sm font-medium text-muted-foreground">
                  Hit Send to get a response
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  },
);
ApiPlaygroundBlock.displayName = "ApiPlaygroundBlock";

"use client";

import React from "react";

export interface ApiThemeStyles {
  bg: string;
  text: string;
  border: string;
  tabBorder?: string;
  checkboxBorder?: string;
  glow: string;
}

const colorThemes: Record<string, ApiThemeStyles> = {
  primary: {
    bg: "bg-primary text-primary-foreground",
    text: "text-primary",
    border: "border-primary/30",
    tabBorder: "border-primary",
    checkboxBorder: "border-primary",
    glow: "shadow-[0_0_15px_var(--primary)]",
  },
  default: {
    bg: "bg-primary text-primary-foreground",
    text: "text-primary",
    border: "border-primary/30",
    tabBorder: "border-primary",
    checkboxBorder: "border-primary",
    glow: "shadow-[0_0_15px_var(--primary)]",
  },
  lavender: {
    bg: "bg-[#9b8afb] text-white",
    text: "text-[#9b8afb]",
    border: "border-[#9b8afb]/40",
    tabBorder: "border-[#9b8afb]",
    checkboxBorder: "border-[#9b8afb]",
    glow: "shadow-[0_0_15px_rgba(155,138,251,0.35)]",
  },
  indigo: {
    bg: "bg-indigo-600 text-white",
    text: "text-indigo-600 dark:text-indigo-400",
    border: "border-indigo-500",
    tabBorder: "border-indigo-500",
    checkboxBorder: "border-indigo-500",
    glow: "shadow-[0_0_15px_rgba(99,102,241,0.3)]",
  },
  rose: {
    bg: "bg-rose-600 text-white",
    text: "text-rose-600 dark:text-rose-400",
    border: "border-rose-500",
    tabBorder: "border-rose-500",
    checkboxBorder: "border-rose-500",
    glow: "shadow-[0_0_15px_rgba(225,29,72,0.3)]",
  },
  emerald: {
    bg: "bg-emerald-600 text-white",
    text: "text-emerald-600 dark:text-emerald-400",
    border: "border-emerald-500",
    tabBorder: "border-emerald-500",
    checkboxBorder: "border-emerald-500",
    glow: "shadow-[0_0_15px_rgba(16,185,129,0.3)]",
  },
  zinc: {
    bg: "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900",
    text: "text-zinc-900 dark:text-zinc-100",
    border: "border-zinc-900 dark:border-zinc-100",
    tabBorder: "border-zinc-900 dark:border-zinc-100",
    checkboxBorder: "border-zinc-900 dark:border-zinc-100",
    glow: "shadow-[0_0_15px_rgba(255,255,255,0.2)] dark:shadow-[0_0_15px_rgba(255,255,255,0.2)]",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

const themeVarsMap: Record<string, { color: string; glow: string }> = {
  primary: { color: "var(--primary)", glow: "var(--primary)" },
  default: { color: "var(--primary)", glow: "var(--primary)" },
  lavender: { color: "#9b8afb", glow: "rgba(155, 138, 251, 0.35)" },
  indigo: { color: "#6366f1", glow: "rgba(99, 102, 241, 0.3)" },
  rose: { color: "#e11d48", glow: "rgba(225, 29, 72, 0.3)" },
  emerald: { color: "#10b981", glow: "rgba(16, 185, 129, 0.3)" },
  zinc: { color: "#18181b", glow: "rgba(255, 255, 255, 0.2)" },
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        bg: "bg-[var(--api-color)] text-white",
        text: "text-[var(--api-color)]",
        border: "border-[var(--api-color)]",
        tabBorder: "border-[var(--api-color)]",
        checkboxBorder: "border-[var(--api-color)]",
        glow: "shadow-[0_0_15px_var(--api-glow)]",
      },
      style: {
        "--api-color": color,
        "--api-glow": `rgba(${rgb}, 0.3)`,
      } as React.CSSProperties,
    };
  }

  const resolvedTheme = colorThemes[color] || colorThemes.primary;
  const vars = themeVarsMap[color] || themeVarsMap.primary;

  return {
    theme: resolvedTheme,
    style: {
      "--api-color": vars.color,
      "--api-glow": vars.glow,
    } as React.CSSProperties,
  };
};

"use client";

import { cn } from "@/lib/utils";
import { AlertCircle, Check, ChevronDown, Search, X } from "lucide-react";
import React, { forwardRef, useEffect, useMemo, useRef, useState } from "react";
import { getThemeStyles } from "./select-theme";

// ==========================================
// DYNAMIC THEME ENGINE
// ==========================================
export type SelectColor = "indigo" | "rose" | "emerald" | "zinc" | string;
export type SelectVariant = "default" | "filled" | "underlined" | "glow" | "glass";
export type SelectSize = "sm" | "md" | "lg";

// ==========================================
// SELECT COMPONENT
// ==========================================
export interface SelectOption {
  label: string;
  value: string;
  icon?: React.ElementType;
  group?: string; // Added for nested/grouped options
}

// Walks up the tree to the first ancestor that clips its overflow (a modal
// shell, a scroll pane, a card with overflow-hidden). That element — not the
// viewport — is what actually crops the dropdown, so it defines the space the
// menu has to work with. Returns null when nothing clips, meaning the viewport
// is the only bound. Only overflow-y counts: the menu grows vertically, and a
// box that clips just sideways (overflow-x: clip, e.g. a slide-in stage) leaves
// it free to hang below — treating that as a clip flipped the menu up into it.
const getClippingRect = (el: HTMLElement): DOMRect | null => {
  let node = el.parentElement;
  while (node && node !== document.body) {
    const { overflowY } = window.getComputedStyle(node);
    if (/(auto|scroll|hidden|clip)/.test(overflowY)) {
      return node.getBoundingClientRect();
    }
    node = node.parentElement;
  }
  return null;
};

/** Everything the two selection modes share. */
interface SelectBlockBaseProps {
  options: SelectOption[];
  placeholder?: string;
  variant?: SelectVariant;
  color?: SelectColor;
  inputSize?: SelectSize;
  label?: string;
  helperText?: string;
  error?: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  className?: string;
  /** Adds a filter box above the options. */
  searchable?: boolean;
}

/** The default: one option at a time, so the value is a plain string. */
export interface SelectBlockSingleProps extends SelectBlockBaseProps {
  multiple?: false;
  value?: string;
  onChange?: (value: string) => void;
}

/** `multiple` — value and callback both deal in arrays. */
export interface SelectBlockMultipleProps extends SelectBlockBaseProps {
  multiple: true;
  value?: string[];
  onChange?: (value: string[]) => void;
}

/**
 * Discriminated on `multiple`, so a single select hands your callback a
 * `string` and a multi select hands it a `string[]` — neither needs a cast,
 * and passing a `setState` straight in just works.
 */
export type SelectBlockProps = SelectBlockSingleProps | SelectBlockMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type SelectBlockImplProps = SelectBlockBaseProps & {
  multiple?: boolean;
  value?: string | string[];
  onChange?: (value: string | string[]) => void;
};

const SelectBlockImpl = forwardRef<HTMLDivElement, SelectBlockImplProps>(
  (
    {
      options = [],
      value,
      onChange,
      placeholder = "Select an option",
      variant = "default",
      color = "primary",
      inputSize = "md",
      label,
      helperText,
      error,
      icon,
      disabled = false,
      className,
      multiple = false,
      searchable = false,
    },
    ref,
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [dropUp, setDropUp] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const selectRef = useRef<HTMLDivElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const { theme, style } = getThemeStyles(color);

    // selectRef drives the click-outside and drop-direction logic, so the
    // forwarded ref is mirrored onto it rather than replacing it.
    React.useImperativeHandle(ref, () => selectRef.current as HTMLDivElement);

    const hasError = Boolean(error);

    // Filter options based on search
    const filteredOptions = useMemo(() => {
      if (!searchQuery) return options;
      return options.filter((opt) =>
        opt.label.toLowerCase().includes(searchQuery.toLowerCase()),
      );
    }, [options, searchQuery]);

    // Group options if "group" property is provided
    const groupedOptions = useMemo(() => {
      return filteredOptions.reduce(
        (acc, opt) => {
          const group = opt.group || "ungrouped";
          if (!acc[group]) acc[group] = [];
          acc[group].push(opt);
          return acc;
        },
        {} as Record<string, SelectOption[]>,
      );
    }, [filteredOptions]);

    // Focus search input automatically when opened
    useEffect(() => {
      if (isOpen && searchable && searchInputRef.current) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
      if (!isOpen) setSearchQuery("");
    }, [isOpen, searchable]);

    // Close dropdown on click outside
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          selectRef.current &&
          !selectRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
        }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () =>
        document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Decide which way the menu opens *before* it becomes visible, so it never
    // renders in the wrong place for a frame. The menu is always mounted (it is
    // only hidden via opacity), so its height is measurable while closed.
    const handleToggle = () => {
      if (!isOpen && selectRef.current) {
        const trigger = selectRef.current.getBoundingClientRect();
        const clip = getClippingRect(selectRef.current);
        const menuHeight = dropdownRef.current?.offsetHeight ?? 240;

        const bottomBound = Math.min(
          window.innerHeight,
          clip ? clip.bottom : Number.POSITIVE_INFINITY,
        );
        const topBound = Math.max(0, clip ? clip.top : 0);

        const spaceBelow = bottomBound - trigger.bottom - 8;
        const spaceAbove = trigger.top - topBound - 8;

        // Only flip when below genuinely can't fit and above is roomier.
        setDropUp(spaceBelow < menuHeight && spaceAbove > spaceBelow);
      }
      setIsOpen(!isOpen);
    };

    const handleSelect = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple) {
        const currentValues = Array.isArray(value) ? value : [];
        const newValues = currentValues.includes(optValue)
          ? currentValues.filter((v) => v !== optValue)
          : [...currentValues, optValue];
        if (onChange) onChange(newValues);
      } else {
        if (onChange) onChange(optValue);
        setIsOpen(false);
      }
    };

    const handleRemoveTag = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple && Array.isArray(value)) {
        if (onChange) onChange(value.filter((v) => v !== optValue));
      }
    };

    // --- Size Classes ---
    const sizeClasses = {
      sm: {
        wrapper: "min-h-9 px-3 py-1.5",
        text: "text-xs",
        icon: "w-3.5 h-3.5",
        option: "px-3 py-2 text-xs",
        tag: "px-1.5 py-0.5 text-[10px]",
      },
      md: {
        wrapper: "min-h-11 px-4 py-2.5",
        text: "text-sm",
        icon: "w-4 h-4",
        option: "px-4 py-2.5 text-sm",
        tag: "px-2 py-1 text-xs",
      },
      lg: {
        wrapper: "min-h-14 px-5 py-3.5",
        text: "text-base",
        icon: "w-5 h-5",
        option: "px-5 py-3 text-base",
        tag: "px-2.5 py-1 text-sm",
      },
    };
    const s = sizeClasses[inputSize];

    // --- Variant Styles ---
    const getVariantStyles = () => {
      const baseWrapper = cn(
        "relative flex items-center justify-between w-full transition-all duration-300 cursor-pointer outline-none",
        s.wrapper,
      );

      if (disabled)
        return {
          wrapper: cn(
            baseWrapper,
            "opacity-50 cursor-not-allowed border border-border bg-muted",
          ),
          active: "",
        };
      if (hasError)
        return {
          wrapper: cn(
            baseWrapper,
            "border border-red-500 bg-background",
            variant === "underlined" && "border-0 border-b-2 rounded-none",
            variant !== "underlined" && "rounded-xl",
          ),
          active: "ring-4 ring-red-500/10",
        };

      switch (variant) {
        case "filled":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-muted border border-transparent rounded-xl",
            ),
            active: cn("bg-background ring-4", theme.ring),
          };
        case "underlined":
          return {
            wrapper: cn(
              baseWrapper,
              "border-b-2 border-border bg-transparent rounded-none px-0",
            ),
            active: theme.ring.split(" ")[1],
          };
        case "glow":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: theme.glow,
          };
        case "glass":
          return {
            wrapper: cn(
              baseWrapper,
              "min-h-[38px] px-3 py-2 text-sm border-black/15 text-neutral-900 bg-black/5 hover:bg-black/10 focus:bg-white/40 focus:border-black/30 dark:border-white/25 dark:text-white dark:bg-white/10 dark:hover:bg-white/15 dark:focus:bg-white/20 dark:focus:border-white/50 border rounded-md shadow-xs transition-all",
            ),
            active: "ring-2 ring-black/10 dark:ring-white/20 border-black/30 dark:border-white/40 bg-black/10 dark:bg-white/15",
          };
        case "default":
        default:
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: cn("ring-4", theme.ring),
          };
      }
    };

    const styles = getVariantStyles();

    // Renders the selected content (Tags for multi, text for single)
    const renderSelectedContent = () => {
      if (multiple && Array.isArray(value) && value.length > 0) {
        return (
          <div className="flex flex-wrap items-center gap-1.5 w-full pr-6 overflow-hidden">
            {value.map((val) => {
              const opt = options.find((o) => o.value === val);
              if (!opt) return null;
              return (
                <span
                  key={val}
                  onClick={(e) => handleRemoveTag(val, e)}
                  className={cn(
                    "inline-flex items-center gap-1 font-semibold rounded-md border border-transparent hover:border-red-200 dark:hover:border-red-900 transition-colors",
                    s.tag,
                    theme.bgSoft,
                  )}
                >
                  {opt.label}
                  <X
                    className={cn("shrink-0 hover:text-red-500", s.icon)}
                    style={{ width: "0.8em", height: "0.8em" }}
                  />
                </span>
              );
            })}
          </div>
        );
      }

      const singleOption = options.find((opt) => opt.value === value);
      return (
        <span
          className={cn(
            "truncate pr-6",
            s.text,
            !singleOption
              ? variant === "glass" ? "text-neutral-500 dark:text-white/60" : "text-muted-foreground"
              : variant === "glass" ? "text-neutral-900 font-medium dark:text-white" : "text-foreground",
          )}
        >
          {singleOption ? singleOption.label : placeholder}
        </span>
      );
    };

    return (
      <div
        ref={selectRef}
        className={cn("flex flex-col gap-1.5 w-full relative", className)}
        style={style}
      >
        {label && (
          <label
            className={cn(
              "text-sm font-semibold",
              hasError ? "text-red-500" : variant === "glass" ? "text-white/90" : "text-foreground",
              disabled && "opacity-50",
            )}
          >
            {label}
          </label>
        )}

        {/* Trigger Button */}
        <button
          type="button"
          disabled={disabled}
          onClick={handleToggle}
          className={cn(
            styles.wrapper,
            isOpen && styles.active,
            multiple && Array.isArray(value) && value.length > 0 && "py-1.5",
          )}
        >
          <div className="flex items-center gap-2 overflow-hidden w-full">
            {icon && (
              <div
                className={cn(
                  "shrink-0 text-muted-foreground",
                  isOpen && theme.text,
                )}
              >
                {icon}
              </div>
            )}
            {renderSelectedContent()}
          </div>

          <div className="absolute right-4 flex items-center gap-2 shrink-0 bg-transparent">
            {hasError && <AlertCircle className={cn(s.icon, "text-red-500")} />}
            <ChevronDown
              className={cn(
                s.icon,
                variant === "glass" ? "text-neutral-700 dark:text-white/70" : "text-muted-foreground",
                "transition-transform duration-300",
                isOpen && "rotate-180",
                isOpen && theme.text,
              )}
            />
          </div>
        </button>

        {/* Dropdown Menu */}
        <div
          ref={dropdownRef}
          className={cn(
            "absolute left-0 right-0 z-50 overflow-hidden border rounded-xl shadow-2xl transition-all duration-200 ease-out",
            variant === "glass"
              ? "bg-white/50 dark:bg-black/60 backdrop-blur-3xl border border-white/50 dark:border-white/20 text-neutral-900 dark:text-white shadow-2xl"
              : "bg-popover text-popover-foreground border-border",
            dropUp
              ? cn(
                  "origin-bottom",
                  variant === "underlined"
                    ? "bottom-[100%]"
                    : "bottom-[calc(100%+8px)]",
                )
              : cn(
                  "origin-top",
                  variant === "underlined"
                    ? "top-[100%]"
                    : "top-[calc(100%+8px)]",
                ),
            isOpen
              ? "opacity-100 scale-y-100 translate-y-0 pointer-events-auto"
              : cn(
                  "opacity-0 scale-y-95 pointer-events-none",
                  dropUp ? "translate-y-2" : "-translate-y-2",
                ),
          )}
        >
          {searchable && (
            <div className="p-2 border-b border-border bg-muted/50">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <input
                  ref={searchInputRef}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onClick={(e) => e.stopPropagation()}
                  placeholder="Search options..."
                  className="w-full pl-9 pr-3 py-2 bg-card border border-border rounded-lg text-sm text-foreground outline-none focus:ring-2 focus:border-transparent transition-all"
                  style={{ "--tw-ring-color": `var(--theme-color)` } as React.CSSProperties}
                />
              </div>
            </div>
          )}

          <div className="max-h-60 overflow-y-auto p-1 flex flex-col gap-0.5 scrollbar-thin scrollbar-thumb-border">
            {Object.keys(groupedOptions).length === 0 ? (
              <div className="px-4 py-3 text-sm text-muted-foreground text-center">
                No results found
              </div>
            ) : (
              Object.entries(groupedOptions).map(([group, opts]) => (
                <div key={group} className="flex flex-col gap-0.5">
                  {/* Group Header */}
                  {group !== "ungrouped" && (
                    <div className="px-3 py-2 mt-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
                      {group}
                    </div>
                  )}
                  {/* Options */}
                  {opts.map((opt) => {
                    const isSelected =
                      multiple && Array.isArray(value)
                        ? value.includes(opt.value)
                        : value === opt.value;
                    const OptIcon = opt.icon;
                    return (
                      <button
                        key={opt.value}
                        type="button"
                        onClick={(e) => handleSelect(opt.value, e)}
                        className={cn(
                          "w-full flex items-center justify-between rounded-lg transition-colors font-medium text-left cursor-pointer active:scale-[0.98]",
                          s.option,
                          isSelected
                            ? cn(theme.bgSoft, theme.text, "font-semibold shadow-xs")
                            : cn(
                                variant === "glass"
                                  ? "text-neutral-900 dark:text-white/90"
                                  : "text-foreground",
                                theme.hoverBg,
                              ),
                        )}
                      >
                        <div className="flex items-center gap-2">
                          {multiple && (
                            <div
                              className={cn(
                                "w-4 h-4 rounded-[4px] border flex items-center justify-center transition-colors",
                                isSelected
                                  ? cn(theme.bg, "border-transparent")
                                  : "border-input bg-card",
                              )}
                            >
                              {/* No hardcoded colour: theme.bg already carries the
                                  correct contrasting text colour for each theme
                                  (text-white for indigo/rose/hex, but
                                  text-primary-foreground for "primary", which
                                  inverts in dark mode). */}
                              {isSelected && (
                                <Check className="w-3 h-3" strokeWidth={3} />
                              )}
                            </div>
                          )}
                          {OptIcon && <OptIcon className={s.icon} />}
                          <span>{opt.label}</span>
                        </div>
                        {isSelected && !multiple && (
                          <Check
                            className={cn(s.icon, theme.text)}
                            strokeWidth={3}
                          />
                        )}
                      </button>
                    );
                  })}
                </div>
              ))
            )}
          </div>
        </div>

        {error && (
          <p className="text-xs font-semibold text-red-500 flex items-center gap-1 mt-0.5">
            <AlertCircle className="w-3.5 h-3.5" /> {error}
          </p>
        )}
        {helperText && !error && (
          <p className="text-xs font-medium text-muted-foreground mt-0.5">
            {helperText}
          </p>
        )}
      </div>
    );
  },
);
SelectBlockImpl.displayName = "SelectBlock";

/**
 * The implementation is written against the collapsed props; this cast is
 * what hands callers the discriminated pair instead.
 */
export const SelectBlock = SelectBlockImpl as React.ForwardRefExoticComponent<
  SelectBlockProps & React.RefAttributes<HTMLDivElement>
>;

